CREATE TABLE sellers (id VARCHAR(120) PRIMARY KEY, owner_user_id VARCHAR(120) NOT NULL, display_name VARCHAR(200) NOT NULL, legal_name VARCHAR(240) NOT NULL, email VARCHAR(320) NOT NULL, phone VARCHAR(40), status VARCHAR(30) NOT NULL, profile_json JSONB NOT NULL DEFAULT '{}'::jsonb, version BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(owner_user_id), UNIQUE(email));
CREATE TABLE seller_users (seller_id VARCHAR(120) NOT NULL, user_id VARCHAR(120) NOT NULL, role VARCHAR(40) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(seller_id,user_id));
CREATE TABLE seller_verification (seller_id VARCHAR(120) PRIMARY KEY, state VARCHAR(30) NOT NULL, notes VARCHAR(2000), document_hashes JSONB NOT NULL DEFAULT '[]'::jsonb, reviewed_by VARCHAR(120), reviewed_at TIMESTAMPTZ);
CREATE TABLE seller_commission_rules (id VARCHAR(120) PRIMARY KEY, seller_id VARCHAR(120), category_id VARCHAR(120), product_id VARCHAR(120), rate_bps INT NOT NULL CHECK(rate_bps BETWEEN 0 AND 10000), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE seller_ledger (id VARCHAR(120) PRIMARY KEY, seller_id VARCHAR(120) NOT NULL, entry_type VARCHAR(30) NOT NULL, reference_id VARCHAR(160) NOT NULL, amount_minor BIGINT NOT NULL, currency CHAR(3) NOT NULL, description VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(seller_id,reference_id,entry_type));
CREATE TABLE seller_settlements (id VARCHAR(120) PRIMARY KEY, seller_id VARCHAR(120) NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, gross_minor BIGINT NOT NULL, commission_minor BIGINT NOT NULL, refund_minor BIGINT NOT NULL, net_minor BIGINT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(seller_id,period_start,period_end));
CREATE TABLE seller_payouts (id VARCHAR(120) PRIMARY KEY, seller_id VARCHAR(120) NOT NULL, settlement_id VARCHAR(120) NOT NULL, amount_minor BIGINT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE seller_order_items (id BIGSERIAL PRIMARY KEY, event_id VARCHAR(120) NOT NULL, order_id VARCHAR(120) NOT NULL, seller_id VARCHAR(120) NOT NULL, product_id VARCHAR(120) NOT NULL, variant_id VARCHAR(120) NOT NULL, quantity INT NOT NULL, line_total_minor BIGINT NOT NULL, currency CHAR(3) NOT NULL, order_status VARCHAR(40), occurred_at TIMESTAMPTZ NOT NULL, UNIQUE(event_id,variant_id));
CREATE TABLE seller_inbox_events (event_id VARCHAR(120) PRIMARY KEY, event_type VARCHAR(120) NOT NULL, processed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE seller_dlq (id BIGSERIAL PRIMARY KEY, event_id VARCHAR(120), event_type VARCHAR(120), aggregate_id VARCHAR(120), payload_json JSONB, error_message VARCHAR(2000) NOT NULL, failed_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(event_id,error_message));
CREATE TABLE seller_outbox_events (id VARCHAR(120) PRIMARY KEY, aggregate_type VARCHAR(80) NOT NULL, aggregate_id VARCHAR(120) NOT NULL, event_type VARCHAR(120) NOT NULL, schema_version INT NOT NULL DEFAULT 1, occurred_at TIMESTAMPTZ NOT NULL, correlation_id VARCHAR(120) NOT NULL, payload_json JSONB NOT NULL, published_at TIMESTAMPTZ);
CREATE INDEX seller_orders_owner_idx ON seller_order_items(seller_id,occurred_at DESC);
